By placing Eqs.~(\ref{Eq: phi_Ni}) - (\ref{Eq:phi_W}) in Eq.~(\ref{Eq: bc's}%
), one can derive the following scattering amplitudes
\begin{subequations}
\label{Eq:R_up-dn}
\begin{equation}
R_{\uparrow }=a_{+}T_{+}+a_{-}T_{-}-\cos \frac{\theta }{2}e^{-i\phi /2}
\tag{S9a}  \label{Eq:R_up}
\end{equation}%
\begin{equation}
R_{\downarrow }=b_{+}T_{+}+b_{-}T_{-}-\sin \frac{\theta }{2}e^{i\phi /2}
\tag{S9b}\,,   \label{Eq:R_dn}
\end{equation}%
\end{subequations}
where
\begin{subequations}
\label{T_pm}
\begin{equation}
T_{+}=\frac{2\left( B_{-}\cos \frac{\theta }{2}e^{-i\phi /2}-A_{-}\sin \frac{%
\theta }{2}e^{i\phi /2}\right) }{A_{+}B_{-}-A_{-}B_{+}}  \tag{S10a}
\label{Eq:T+}
\end{equation}%
\begin{equation}
T_{-}=\frac{2\left( A_{+}\sin \frac{\theta }{2}e^{i\phi /2}-B_{+}\cos \frac{%
\theta }{2}e^{-i\phi /2}\right) }{A_{+}B_{-}-A_{-}B_{+}}  \tag{S10b}
\label{Eq:T_}
\end{equation}%
\end{subequations}
with
\begin{subequations}
\begin{equation}
A_{s}=\left( 1-\frac{m_{e}va}{\hbar ^{2}k_{N,z}}\right) a_{s}-\frac{%
2m_{0}a^{2}m_{e}k_{z,s}}{\hbar ^{2}k_{N,z}}b_{s}  \tag{S11a}
\end{equation}%
\begin{equation}
B_{s}=\left( 1+\frac{m_{e}va}{\hbar ^{2}k_{N,z}}\right) b_{s}-\frac{%
2m_{0}a^{2}m_{e}k_{z,s}}{\hbar ^{2}k_{N,z}}a_{s}  \tag{S11b}
\end{equation}%
\end{subequations}
and $s$ denoting $+$ or $-$. We note that $R_{\uparrow \left( \downarrow
\right) }$ and $T_{\pm }$ contain only quadratic terms of $k_{x}^{2}$ and $%
k_{y}^{2}$ -- a property that is useful in determining the presence of the
in-plane charge current in a given direction. Next, we determine the transmission matrix by rewriting the transmitted
state in the form of $\varphi _{W}\left(z\right) =\hat{T}%
_{NW}\varphi _{N,i}\left( 0^{+}\right) $. Inserting the expressions of $%
T_{\pm }$ [Eqs.~(\ref{Eq:T+}) and (\ref{Eq:T_})] in Eq.~(\ref{Eq:phi_W}),
one can rewrite $\varphi _{W}\left( z\right) $ as
\begin{widetext}
\begin{equation}
\varphi _{W}\left(z\right) =\frac{2}{A_{+}B_{-}-A_{-}B_{+}}\left(
\begin{array}{cc}
a_{+}B_{-}e^{ik_{z,+}z}-a_{-}B_{+}e^{ik_{z,-}z} &
a_{-}A_{+}e^{ik_{z,-}z}-a_{+}A_{-}e^{ik_{z,+}z} \\
b_{+}B_{-}e^{ik_{z,+}z}-b_{-}B_{+}e^{ik_{z,-}z} &
b_{-}A_{+}e^{ik_{z,-}z}-b_{+}A_{-}e^{ik_{z,+}z}%
\end{array}%
\right) \binom{\cos \frac{\theta }{2}e^{-i\phi /2}}{\sin \frac{\theta }{2}%
e^{i\phi /2}} \,. \tag{S12}
\end{equation}%
\end{widetext}
It follows that the transmission matrix can be expressed as
\begin{equation}
\hat{T}_{NW}=\frac{2}{A_{+}B_{-}-A_{-}B_{+}}\sum\limits_{s=\pm
}se^{ik_{z,s}z}\binom{a_{s}}{b_{s}}\otimes \left(
\begin{array}{cc}
B_{-s} & -A_{-s}%
\end{array}%
\right) \,,  \tag{S13}
\end{equation}%
where $\otimes $ denotes a direct product.

