\end{gather}
 where the $c$'s are fermionic operators. In terms of the time dependent Bogoliubov coefficients, the heating reads as
\begin{gather}
\langle H \rangle=2\sum_{q\neq0}
\omega(q)|v_q(t)|^2+g(q,t)\textmd{Re}[u_q(t)v_q^*(t)]=E_{gs}\left[1-
\left(\frac{\tau_0}{\tau}\right)^2
\ln\left(1+\left(\frac{\tau}{\tau_0}\right)^2\right)
\right]\;,
\end{gather}
where both terms contribute in $(g_2/v)^2$ order. For a linear quench and $t\geq \tau$,
\begin{gather}
v(q,t)=\frac{ig_2(q)|q|}{4\omega^2(q)\tau}\left[\exp(i\omega(q)(t-2\tau))-\exp(i\omega(q)t)+2i\omega(q)\tau\exp(-i\omega(q)t)\right]
\end{gather}
and 
\begin{gather}
u(q,t)=\exp(-i\omega(q)t)
\end{gather}
to lowest order in $g_2$. Consequently, 
\begin{gather}
\textmd{Re}[u_q(t)v_q^*(t)]=-\frac{g_2(q)}{2v}\left(1+\frac{\sin(2v|q|(t-\tau))-\sin(2v|q|t)}{2v|q|\tau}\right)
\label{reuv}
\end{gather}
to lowest order in $g_2/v$. In the steady state ($t\rightarrow \infty$), the trigonometric functions average to zero and only the $-g_2(q)/2v$ factor determines the response.

