\begin{equation}
\epsilon_{\rho,\sigma} \leq 2\Vert A \Vert_{\max}^2.
\end{equation}

\vspace{.7cm}
\paragraph{Extended matrices.}
We define the Hermitian extended matrix $\tilde{A}$ of a complex-valued, not necessarily square matrix $A\in\mathbb{C}^{M\times N}$ as
\begin{equation}\label{}
\tilde{A}=\left[\begin{array}{cc}
0 & A\\
A^{\dagger} & 0
\end{array}\right]\in\mathbb{C}^{(M+N)\,\times\,(M+N)}.
\end{equation}
Using block matrix identities for the determinant, we obtain its characteristic
polynomial
\begin{equation}
\chi_{\tilde{A}}(\lambda)=\lambda^{\vert M-N\vert}\,\det\,(\lambda\mathbbm{1}+\sqrt{AA^{\dagger}})(\lambda\mathbbm{1}-\sqrt{AA^{\dagger}}).
\end{equation}
The eigenvalues of $\tilde{A}$ are either zero or correspond to $\{\pm\sigma_{j}\}$, the singular values of $A$ for $j=1,\dots,r$ with an additional sign. Hence, if $A$ has low rank $r$, then $\tilde{A}$ has low rank $2r$. The corresponding eigenvectors
are proportional to $(u_{j},\pm v_{j})\in\mathbb{C}^{M+N}$ since
\begin{eqnarray}
\left[\begin{array}{cc}
\mp\sigma_{j}\mathbbm{1} & A\\
A^{\dagger} & \mp\sigma_{j}\mathbbm{1}
\end{array}\right]\cdot\left[\begin{array}{c}
u_{j}\\
\pm v_{j}
\end{array}\right]=0,
\end{eqnarray}
where $u_j$ and $v_j$ are the $j$th left and right singular vector of~$A$, respectively. The important point is that the eigenvectors of the extended matrix
preserve the correct phase relations between the left and right singular
vectors since
$(\mathrm{e}^{\mathrm{i}\vartheta_{j}} u_{j}, \pm v_{j})$  is
 only an eigenvector of $\tilde A$ for the correct phase $\mathrm{e}^{\mathrm{i}\vartheta_{j}}=1$,
\begin{align}\nonumber
\left[\begin{array}{cc}
\mp\sigma_{j}\mathbbm{1} & A\\
A^{\dagger} & \mp\sigma_{j}\mathbbm{1}
\end{array}\right]
\!\cdot\!\left[\begin{array}{c}
\mathrm{e}^{\mathrm{i}\vartheta_{j}}u_{j}\\
\pm v_{j}
\end{array}\right]=&\left[\begin{array}{c}
\mp\sigma_{j}\mathrm{e}^{\mathrm{i}\vartheta_{j}}u_{j}\pm Av_{j}\\
\mathrm{e}^{\mathrm{i}\vartheta_{j}}A^{\dagger}u_{j}-\sigma_{j}v_{j}
\end{array}\right]\\=&(\mathrm{e}^{\mathrm{i}\vartheta_{j}}-1)\sigma_{j}\left[\begin{array}{c}
\mp u_{j}\\
 v_{j}
\end{array}\right].
\end{align}
The right hand side is only equal to zero for the correct phase $\mathrm{e}^{\mathrm{i}\vartheta_{j}}=1$. 

\paragraph{Low-rank Procrustes.}
Let the isometry be $W=U V^\dagger$ with $U\in\mathbb{C}^{M\times r}$ and $V\in\mathbb{C}^{N\times r}$. Assume that $M>N$, giving orthogonal columns in the full-rank Procrustes problem ($r=N$). We find for the low-rank (partial) isometry that
\begin{equation}
W^\dagger W = V U^\dagger U V^\dagger =V V^\dagger = \sum_{j=1}^r \vec v_j \vec v_j^\dagger.
\end{equation}
Pick an arbitrary vector 
$\vec x = \sum_{j=1}^r \alpha_j \vec v_j + \vec x^\perp= \vec x^\parallel+ \vec x^\perp$.
where $\vec x^\perp$ denotes the part orthogonal to the orthonormal vectors $\vec v_j$. Then,
\begin{equation}
W^\dagger W \vec x = \sum_{j=1}^r \alpha_j \vec v_j = \vec x^\parallel.
\end{equation}
Thus, $W^\dagger W$ acts as the identity operator in the low-rank subspace, and projects out the space perpendicular to that subspace.


