\section{The Polynomial method for solving Combinatorial problems with bounded size destabilizers}

\begin{thm}
If $\left|\Sigma_N \smallsetminus \mbox{\rm Stab}({\mathcal F})\right|= c \le c_0 $ for some constant $c_0$ then the problem of determining $Z({\mathcal F})$ is in co-NP. 
\end{thm}
\begin{proof}
We wish to determine whether the following algebraic variety is non-empty.
\begin{align*}
Z({\mathcal F}) = \setof{(x_1,\ldots,x_N) \in \setof{0,1}^N \mid f_k(x_1,\ldots,x_N) = 0 \text{ for each }1 \leq k \leq K}
\end{align*}
Consider the following iteration
\begin{equation}
\begin{array}{c}
f_{k,\left\{ \sigma_{1},\,\sigma_{2}\right\} }=\left(\sigma_{1}\circ f_k \right)\cdot \left(\sigma_{2}\circ f_k\right)\mod {\mathcal I}\\
\vdots\\
f_{k,\left\{ \sigma_{0},\cdots,\,\sigma_{c-1} \right\} }=f_{k,\left\{ \sigma_{0},\cdots,\sigma_{c-2}\right\} }\cdot\left( \sigma_{c-1}\circ f_k \right)\mod {\mathcal I}
\end{array}
\end{equation}
where 
\begin{equation*}
 \Sigma_N \smallsetminus \mbox{\rm Stab}({\mathcal F}) := \left\{ \sigma_{0},\cdots,\,\sigma_{c-1} \right\}.
\end{equation*}
So as to induce the following set of polynomials each having at most $n^c$ terms, 
all square free. 
\begin{equation}
{\mathcal G}:=\left\{ f_{k,\left\{ \sigma_{0},\cdots,\,\sigma_{c-1} \right\} } \right\} _{0\le k<N}.
\end{equation}
We can determine a polynomial $p\left(x_{0}\right)$ in a single variable
\begin{equation}
p\left(x_{0}\right)=\prod_{0\le t<N}\left(x_{0}-\beta_{t}\right)
\end{equation}
in the ideal generated by the polynomials in ${\mathcal G}$ i.e. $\exists\;\left\{h_k \right\} _{0\le k<n}\subset{\mathcal C}$ such that
\begin{equation}
p\left(x_{0}\right)=\sum_{0\le k<K}h_k\cdot f_{k,\left\{ \sigma_{0},\cdots,\,\sigma_{c -1} \right\} }.
\end{equation}
Henceforth, let $\boldsymbol{\beta}$ denote the vector whose entries are the roots of the polynomial $p\left(x_{0}\right)$. If $\boldsymbol{\beta}$ admits an index $t$ for which $\beta_{t}\notin\mathbb{F}_{2}$
than this fact constitutes a certificate of non existence of solution
to ${\mathcal F}$. However it would be incorrect to conclude that if $\forall\:0\le t<N$,
$\beta_{t}\in\mathbb{F}_{2}$ there should necessarily exist solutions
to ${\mathcal F}$. The criteria invoked above is therfore a necessary but not a sufficient condition for
the existence of solution to ${\mathcal F}$. The sufficient condition for the
existence of solution to ${\mathcal F}$ is the fact that the matrix $\mathbf{M}_{{\mathcal F}}$
of size $N\times c$, whose entries are given by 
\begin{equation}
\mathbf{M}_{{\mathcal F}}:=\left(m_{k,\sigma}=\sigma\circ f_{k}\right)
\end{equation}
(where $0 \le k<K$ and $\sigma \in \Sigma_N \smallsetminus \mbox{\rm Stab}({\mathcal F})$), has the property 
that $\mathbf{M}_{{\mathcal F}}\mod\left(\mathbf{x}-\boldsymbol{\beta}\right)$, has at least one zero column.
\end{proof}

