\input{univ-upper}

\input{univ-lower}

For the rest of this section, we recall 
a recent result from \textcite{FFSS2011},
that allows us to
provide the exact complexity of the \MCOL{OCN}\ trace universality problem
in terms of its level in the Fast-Growing Hierarchy.
\begin{definition}[Fast-Growing Hierarchy] \label{def:fastgrowing-hierarchy}
    Consider the family of functions $F_n:\mathbb{N}\to\mathbb{N}$
    where for $x,k\in\mathbb{N}$,

    \begin{align*}
        F_0(x) = x+1 \text{\quad and }
        &&
        F_{k+1}(x) = F_k^{x+1}(x).
    \end{align*}
    Here, $F^k$ denotes the $k$-fold application of $F$. Moreover, define $F_{\omega}(x)=F_x(x)$ for the first limit ordinal $\omega$. For $k\le \omega$,


    $\mathfrak{F}_k$ denotes
    the least class of functions
    that contains all constants and is closed under
    substitution, sum, projections, limited recursion and applications
    of functions $F_n$ for $n\le k$. Already $\mathfrak{F}_2$ contains all elementary functions
    and the union $\bigcup_{k\in\mathbb{N}}\mathfrak{F}_k$ of all finite levels
    contains exactly the primitive-recursive functions. A function is called \emph{Ackermannian} if it is in
    $\mathfrak{F}_{\omega}\setminus\bigcup_{k\in\mathbb{N}}\mathfrak{F}_k$.

\end{definition}

A sequence $x_0, x_1,\dots,x_l$ of macrostates
is called \emph{good} if there are indices $0\le i<j\le l$
such that $x_i\sqsubseteq x_j$ and \emph{bad} otherwise. The sequence is \emph{$t$-controlled} by $f:\mathbb{N}\to\mathbb{N}$
if $\norminf{x_i} < f(i+t)$ for every index $0\le i\le l$.
\begin{theorem}[\cite{FFSS2011}]\label{thm:badseq}
    Let $f:\mathbb{N}\to\mathbb{N}$ be a monotone function in $\mathfrak{F}_\gamma$
    such that $f(x)\ge\max\{1,x\}$ for some $\gamma\ge 1$. There is a function $L_{k,f}(t)$ in $\mathfrak{F}_{k+\gamma-1}$
    that computes a bound on the maximal length of
    bad sequences in $\N_{\bottom}^k$ that are $t$-controlled by $f$.

\end{theorem}

\begin{corollary}
    \MCOL{Trace universality}\ of \MCOL{OCN}\ is Ackermannian.

\end{corollary}
\begin{proof}
    By \cref{thm:univ-ack}, it suffices to show that the problem is
    in $\mathfrak{F}_\omega$. Recall the procedure that, for a given process $pm$ of a net with
    $k$ control-states, guesses a shortest terminating path from the initial
    macrostate
    (a witness for non-universality),
    and stops unsuccessfully if a macrostate covers
    one that has been seen before.

