implementation of SymAE.
$\mathtt{ConvA}$ and $\mathtt{Conv}$ denote convolutional layers with and without $\mathtt{elu}$ activation, respectively. We used $\mathtt{distribute}$ to apply the same layer to each of the instances.



\begin{algorithm}
  \begin{algorithmic}[1]
	\caption{Keras-style algorithm for preparing coherent encoder $\encg$.}
	\label{alg:encg}
  \STATE $\Zg\gets \mathtt{distribute}(\mathtt{ConvA})(\X);\,\Zg\gets \mathtt{distribute}(\mathtt{ConvA})(\Zg);\, \Zg\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zg)$ \hfill\COMMENT{$\encgone$}
  \STATE $\Zg\gets \mathtt{distribute}(\mathtt{ConvA})(\Zg);\,\Zg\gets \mathtt{distribute}(\mathtt{ConvA})(\Zg);\, \Zg\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zg)$ \hfill\COMMENT{$\encgone  $}
  \STATE $\Zg\gets \mathtt{reduce\_mean}(\Zg,\text{axis}=1)$ \hfill\COMMENT{sum over instances}
  \STATE $\Zg\gets \mathtt{ConvA}(\Zg);\, \Zg\gets \mathtt{ConvA}(\Zg);\, \Zg\gets \mathtt{MaxPool}(\Zg)$ \hfill\COMMENT{$\encgtwo$}
  \STATE $\Zg\gets \mathtt{ConvA}(\Zg);\, \Zg\gets \mathtt{ConvA}(\Zg);\, \Zg\gets \mathtt{BatchNormalization}(\Zg)$ \hfill\COMMENT{$\encgtwo$}
  \STATE $\Zg\gets \mathtt{MaxPool}(\Zg);\,\Zg\gets \mathtt{Flatten}(\Zg);\,\Zg\gets \mathtt{Dense}(\Zg, \nZg)$ \hfill\COMMENT{$\encgtwo$}
  \STATE $\encg=\mathtt{Model}(\X, \Zg)$
  \end{algorithmic}
\end{algorithm}

\begin{algorithm}
  \begin{algorithmic}[1]
	\caption{Keras-style algorithm for preparing nuisance encoder $\encs$.}
	\label{alg:encs}
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\X);\,\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\, \Zs\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zs)$
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\,\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\, \Zs\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zs)$
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\,\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\, \Zs\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zs)$
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs);\,\Zs\gets \mathtt{distribute}(\mathtt{ConvA})(\Zs)$
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{BatchNormalization})(\Zs)$
  \STATE $\Zs\gets \mathtt{distribute}(\mathtt{MaxPool})(\Zs);\,\Zs\gets \mathtt{distribute}(\mathtt{Flatten})(\Zs);\,\Zs\gets \mathtt{distribute}(\mathtt{Dense})(\Zs, \nZs)$
  \STATE $\encs=\mathtt{Model}(\X, \Zs)$
  \end{algorithmic}
\end{algorithm}


\begin{algorithm}
  \begin{algorithmic}[1]
  \caption{Fuse latent codes $\Zg$ and $\Zs$.}
	\label{alg:fuse}
  \STATE $\out{\Zs}\gets \mathtt{dropout}(\Zs, \alpha)$ \hfill\COMMENT{stochastic regularization}
  \STATE $\out{\Zg}=\mathtt{RepeatVector}(\ntau)({\Zg});\,\out{\X}\gets\mathtt{concatenate}([\out{\Zg},\out{\Zs}],\text{axis}=2)$ \hfill\COMMENT{distribute coherent code to each instance}



